{"new_string":"/**
 * What both issue-creating tools share: the body an agent wrote, made safe to
 * publish, and the `gh issue create` call itself. The two differ only in what
 * happens AROUND it -- `create_sub_issue` labels and links; `open_root_issue`
 * does neither -- so this returns the number and leaves those to the caller.
 */
function publishIssueBody(body: string, what: string): string {
  // An issue body is read for a command by `resolve_entry_agent.ts` when the issue is
  // opened, so an agent writing one here would start a run on an issue it just created.
  // The route it means is `launch_sub_agent`, which is also what the parent's
  // aggregation waits on.
  refuseCommandLines(
    body,
    `${what} body`,
    "Use `launch_sub_agent` to start an agent on a sub-issue.",
  );
  return notifyTagPrefix(body, "Issue") + withCheckedMentions(body);
}

async function ghCreateIssue(title: string, body: string, labels: string[]): Promise<number> {
  const cmd = ["issue", "create", "--repo", REPO, "--title", title];
  if (body) cmd.push("--body", body);
  for (const l of labels) cmd.push("--label", l);

  const { code, stdout, stderr } = gh(...cmd);
  if (code) mcpFail(stderr || stdout);
  const num = Number(stdout.trim().split("/").pop());
  if (!Number.isFinite(num)) mcpFail(`gh issue create: unexpected output: ${stdout.slice(0, 300)}`);
  return num;
}

async function createSubIssue(a: z.infer<typeof CREATE_SUB_ISSUE_SCHEMA>): Promise<string> {
  const title = a.title;
  const rawBody = a.body ?? "";
  let labels = a.labels ?? [];
  const parentNum = (process.env.ISSUE_NUMBER ?? "").trim();

  // A pull request run does not create sub-issues. It reviews or fixes one pull
  // request, and `ISSUE_NUMBER` on such a run is the pull request's own number (or
  // the parent issue `fetch_events.ts` resolved for context) -- so a sub-issue
  // created here would hang under a node that was never decomposing anything, and
  // the pull request's `atomaton/in-progress` guard would be held by a chain that
  // had moved elsewhere. Decomposition belongs to an issue run. A defect found on
  // this run belongs outside the tree: `open_root_issue`.
  if ((process.env.ATOMATON_RUN_TYPE ?? "").trim() === "pr") {
    mcpFail(
      "create_sub_issue links a child under the issue its run is on, and this run is on a " +
        "pull request, which reviews or fixes one pull request rather than decomposing it. " +
        "Use create_pr to hand this pull request to a reviewer, or request_close_issue to " +
        "conclude it. To report a problem with a tool or the environment, use open_root_issue.",
    );
  }

  // A sub-issue without a parent is the shape #164 was: labelled as a child, linked
  // under nothing, and never aggregated. The name says "sub", so the tool refuses
  // rather than producing one -- the parentless case belongs to `open_root_issue`.
  if (!parentNum) {
    mcpFail(
      "create_sub_issue links a child under the issue its run is on, and this run has no " +
        "current issue (`ISSUE_NUMBER` is empty), so there is no parent to link under. " +
        "To open an issue outside the tree -- a tool defect, an environment fix, a decision " +
        "for a person -- use open_root_issue. To create a child, run on the parent issue.",
    );
  }

  const body = publishIssueBody(rawBody, "issue");
  const subIssueLabel = getLabel("sub_issue");
  const ensured = gh(
    "label", "create", subIssueLabel,
    "--repo", REPO,
    "--force",
    "--color", "8250df",
    "--description", "Child delivery task managed by Atomaton",
  );
  if (ensured.code) mcpFail(`Failed to ensure sub-issue label '${subIssueLabel}': ${ensured.stderr || ensured.stdout}`);
  if (!labels.includes(subIssueLabel)) labels = [...labels, subIssueLabel];

  const num = await ghCreateIssue(title, body, labels);

  // The link IS the record now, so a failure here is a failure of `create_sub_issue`.
  //
  // This used to be best-effort, logged without a severity word, because the
  // `atomaton:parent` tag in the body was what aggregation read and the link was "the
  // cosmetic half". The tag is gone — it recorded the parent at creation and nothing
  // ever rewrote it, so a person re-parenting a sub-issue in the web UI left two
  // answers in the system. See `adapters/github/parent-issue.ts`.
  //
  // The issue exists by this point and cannot be un-created, so the failure names it:
  // an agent that is told only "create_sub_issue failed" would file it again.
  try {
    const pid = await resolveIssueId(Number(parentNum));
    const sid = await resolveIssueId(num);
    ghGraphql(
      "mutation($parent:ID!,$sub:ID!){addSubIssue(input:{issueId:$parent,subIssueId:$sub,replaceParent:true}){issue{number}}}",
      { parent: pid, sub: sid },
    );
    log(`Linked sub-issue #${num} to parent #${parentNum} via official sub-issues API`);
  } catch (e) {
    mcpFail(
      `Issue #${num} was created, but could not be linked under #${parentNum} as a sub-issue: ${e}. ` +
        `Nothing records that edge except the link, so #${num} is currently a root issue and no aggregation ` +
        `will pick it up. Do not create it again — add it under #${parentNum} in the web UI, or retry the link.`,
    );
  }

  logOp("create_sub_issue", { number: num, title, parent: Number(parentNum) });
  // Reaching this line means the link exists: a failed link is a failed call above,
  // and the empty-`ISSUE_NUMBER` case is refused before anything is created.
  return JSON.stringify({
    number: num,
    url: stdoutRef,
    parent: Number(parentNum),
  });
}

async function openRootIssue(a: z.infer<typeof OPEN_ROOT_ISSUE_SCHEMA>): Promise<string> {
  const title = a.title;
  const rawBody = a.body ?? "";
  const labels = a.labels ?? [];

  // The body is published to a thread people read and an entry script reads, so it
  // gets the same treatment a sub-issue's does -- but nothing else is shared. No
  // label, no link, and no read of `ISSUE_NUMBER`: on a pull request run that holds
  // the PR's own number, and linking to it would hang a root under a leaf.
  const body = publishIssueBody(rawBody, "issue");

